-- RLS (ADR 0026). Alerts are a staff tool (0004): their events and the latest evaluation are
-- read with the same scope (the staff that sees the player, admin the whole club). Players and
-- guardians never see them (privacy of minors). The worker writes the evaluation; the events
-- are written only by `alert_event_record` below.
DO $$
DECLARE
  staff constant text := "app_admin"."role_in"('{coach,sc,medical,admin,superadmin}');
  player_scope constant text := '((SELECT "app"."sees_whole_club"()) OR player_id = ANY ((SELECT "app"."visible_player_ids"())::uuid[]))';
BEGIN
  PERFORM "app_admin"."secure_club_table"('public.alert_event',
    format('%s AND %s', staff, player_scope), '{}');
  PERFORM "app_admin"."secure_club_table"('public.player_alert_evaluation',
    format('%s AND %s', staff, player_scope), '{}');
END
$$;
--> statement-breakpoint
-- Append-only: not even the worker writes events directly.
REVOKE INSERT, UPDATE ON "public"."alert_event" FROM "sport_performance_worker";
--> statement-breakpoint

-- The worker generates alerts; the API only reviews them. 0004 let every staff role insert
-- and update any column: now the API updates only the review columns, and the worker also
-- the new episode columns.
REVOKE INSERT, UPDATE ON "public"."alert" FROM "sport_performance_app";
--> statement-breakpoint
GRANT UPDATE ("status", "acknowledged_at", "acknowledged_by", "acknowledgement_note", "updated_at", "updated_by") ON "public"."alert" TO "sport_performance_app";
--> statement-breakpoint
GRANT UPDATE ("current_severity", "last_seen_on", "resolved_on") ON "public"."alert" TO "sport_performance_worker";
--> statement-breakpoint

-- A review by the API: an open alert becomes acknowledged or dismissed, once, by the user of
-- the request, at the database's clock. Reopening (status back to open) is the worker's, when
-- an alert escalates. The owner (migrations, seeds, operators) is not checked.
CREATE FUNCTION "public"."alert_review_guard"() RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp AS $$
BEGIN
  IF (NEW.status, NEW.acknowledged_at, NEW.acknowledged_by, NEW.acknowledgement_note)
       IS DISTINCT FROM (OLD.status, OLD.acknowledged_at, OLD.acknowledged_by, OLD.acknowledgement_note)
     AND EXISTS (SELECT 1 FROM pg_roles r
                  WHERE r.rolname = session_user AND NOT r.rolsuper AND NOT r.rolbypassrls)
     AND pg_has_role(session_user, 'sport_performance_app', 'MEMBER') THEN
    IF OLD.status <> 'open' OR NEW.status = 'open'
       OR NEW.acknowledged_by IS DISTINCT FROM "app"."current_user_id"() THEN
      RAISE EXCEPTION 'An open alert is reviewed once, by the user of the request'
        USING ERRCODE = 'check_violation', CONSTRAINT = 'alert_review', TABLE = 'alert';
    END IF;
    NEW.acknowledged_at := now();
  END IF;
  RETURN NEW;
END;
$$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION "public"."alert_review_guard"() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER "alert_review_guard" BEFORE UPDATE ON "public"."alert"
  FOR EACH ROW EXECUTE FUNCTION "public"."alert_review_guard"();
--> statement-breakpoint

-- The history of an alert, written in the transaction of each change, whoever makes it. The
-- day of a review is the club's today; the other events carry the club day of the episode.
-- Not callable by any connection role: only the trigger (run as the owner) uses it.
CREATE FUNCTION "public"."alert_event_record"() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path = pg_catalog, pg_temp AS $$
DECLARE
  today date;
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO "public"."alert_event" (club_id, alert_id, player_id, type, local_date, severity)
    VALUES (NEW.club_id, NEW.id, NEW.player_id, 'raised', NEW.local_date, NEW.severity);
    RETURN NULL;
  END IF;
  IF OLD.resolved_on IS NOT NULL AND NEW.resolved_on IS NULL THEN
    INSERT INTO "public"."alert_event" (club_id, alert_id, player_id, type, local_date, severity)
    VALUES (NEW.club_id, NEW.id, NEW.player_id, 'reopened', NEW.last_seen_on, NEW.severity);
  END IF;
  IF NEW.severity > OLD.severity THEN
    INSERT INTO "public"."alert_event" (club_id, alert_id, player_id, type, local_date, severity)
    VALUES (NEW.club_id, NEW.id, NEW.player_id, 'escalated', NEW.last_seen_on, NEW.severity);
  END IF;
  IF OLD.status = 'open' AND NEW.status <> 'open' THEN
    SELECT (now() AT TIME ZONE c.time_zone)::date INTO today
      FROM "public"."club" c WHERE c.id = NEW.club_id;
    INSERT INTO "public"."alert_event"
      (club_id, alert_id, player_id, type, local_date, severity, note, actor_id)
    VALUES (NEW.club_id, NEW.id, NEW.player_id, NEW.status::text::"public"."alert_event_type",
            today, NEW.severity, NEW.acknowledgement_note, NEW.acknowledged_by);
  END IF;
  IF OLD.resolved_on IS NULL AND NEW.resolved_on IS NOT NULL THEN
    INSERT INTO "public"."alert_event" (club_id, alert_id, player_id, type, local_date, severity)
    VALUES (NEW.club_id, NEW.id, NEW.player_id, 'resolved', NEW.resolved_on, NEW.severity);
  END IF;
  RETURN NULL;
END;
$$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION "public"."alert_event_record"() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER "alert_event_record" AFTER INSERT OR UPDATE OF "severity", "resolved_on", "status" ON "public"."alert"
  FOR EACH ROW EXECUTE FUNCTION "public"."alert_event_record"();
--> statement-breakpoint
-- Events are history: nobody changes or removes them, not even the owner. Only a cascade from
-- a deleted player or alert (data subject rights) takes them away.
CREATE FUNCTION "public"."alert_event_guard"() RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog, pg_temp AS $$
BEGIN
  IF TG_OP = 'DELETE' AND pg_trigger_depth() > 1 THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'The events of an alert are append-only'
    USING ERRCODE = 'check_violation', CONSTRAINT = 'alert_event_append_only', TABLE = 'alert_event';
END;
$$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION "public"."alert_event_guard"() FROM PUBLIC;
--> statement-breakpoint
CREATE TRIGGER "alert_event_guard" BEFORE UPDATE OR DELETE ON "public"."alert_event"
  FOR EACH ROW EXECUTE FUNCTION "public"."alert_event_guard"();
--> statement-breakpoint

-- ─── Outbox: what re-evaluates alerts without changing a derived value (ADR 0046) ──────
-- A CMJ (result or attempt), a rule (the whole club), the stage, the category and the sport
-- of a player mark `alerts` for the worker, in the transaction of the write. Every
-- recalculation of a player evaluates its alerts, so the other marks need nothing new.
CREATE FUNCTION "public"."alert_refresh_mark"(club uuid, players uuid[]) RETURNS void
LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path = pg_catalog, pg_temp AS $$
BEGIN
  IF club IS NULL OR players IS NULL OR cardinality(players) = 0 THEN
    RETURN;
  END IF;
  INSERT INTO "public"."derived_refresh" AS r (club_id, player_id, alerts, requested_at)
  SELECT club, p.id, true, clock_timestamp()
    FROM "public"."player" p
   WHERE p.club_id = club AND p.id = ANY (players)
  ON CONFLICT (club_id, player_id) DO UPDATE
     SET alerts = true, requested_at = EXCLUDED.requested_at;
  IF FOUND THEN
    PERFORM pg_notify('sport_performance_derived_refresh', club::text);
  END IF;
END;
$$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION "public"."alert_refresh_mark"(uuid, uuid[]) FROM PUBLIC;
--> statement-breakpoint

CREATE FUNCTION "public"."alert_refresh_trigger"() RETURNS trigger
LANGUAGE plpgsql VOLATILE SECURITY DEFINER
SET search_path = pg_catalog, pg_temp AS $$
DECLARE
  rec record;
BEGIN
  CASE TG_TABLE_NAME
  WHEN 'test_result' THEN
    FOR rec IN
      SELECT DISTINCT x.club_id, x.player_id
        FROM (SELECT OLD.club_id, OLD.player_id, OLD.test_definition_id WHERE TG_OP <> 'INSERT'
              UNION ALL
              SELECT NEW.club_id, NEW.player_id, NEW.test_definition_id WHERE TG_OP <> 'DELETE')
             AS x(club_id, player_id, test_definition_id)
        JOIN "public"."test_definition" d ON d.club_id = x.club_id AND d.id = x.test_definition_id
       WHERE d.code = 'cmj'
    LOOP
      PERFORM "public"."alert_refresh_mark"(rec.club_id, ARRAY[rec.player_id]);
    END LOOP;
  WHEN 'test_result_value' THEN
    FOR rec IN
      SELECT r.club_id, r.player_id
        FROM "public"."test_result" r
        JOIN "public"."test_definition" d ON d.club_id = r.club_id AND d.id = r.test_definition_id
       WHERE r.club_id = NEW.club_id AND r.id = NEW.test_result_id AND d.code = 'cmj'
    LOOP
      PERFORM "public"."alert_refresh_mark"(rec.club_id, ARRAY[rec.player_id]);
    END LOOP;
  WHEN 'alert_rule' THEN
    PERFORM "public"."alert_refresh_mark"(
      NEW.club_id, ARRAY(SELECT p.id FROM "public"."player" p WHERE p.club_id = NEW.club_id));
  WHEN 'player_stage', 'player_category' THEN
    IF TG_OP <> 'INSERT' THEN
      PERFORM "public"."alert_refresh_mark"(OLD.club_id, ARRAY[OLD.player_id]);
    END IF;
    IF TG_OP <> 'DELETE' THEN
      PERFORM "public"."alert_refresh_mark"(NEW.club_id, ARRAY[NEW.player_id]);
    END IF;
  WHEN 'player' THEN
    PERFORM "public"."alert_refresh_mark"(NEW.club_id, ARRAY[NEW.id]);
  ELSE
    RAISE EXCEPTION 'alert_refresh_trigger is not attached to %', TG_TABLE_NAME;
  END CASE;
  RETURN NULL;
END;
$$;
--> statement-breakpoint
REVOKE ALL ON FUNCTION "public"."alert_refresh_trigger"() FROM PUBLIC;
--> statement-breakpoint
